{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "meniscus-rehab-intro-2wk",
    "name": "Meniscus Rehab — 2-Week Introductory Block",
    "description": "A 2-week reconditioning starter block for a 36-year-old male recreational lifter recovering from a right medial meniscus tear. Cleared for low-impact strength work. No jumping, no deep knee flexion under load. Prepares the client for progressive loading toward ski-season return.",
    "type": "workout",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "trainer",
      "tags": ["meniscus", "rehab", "strength", "low-impact", "ski-return", "knee-safe"],
      "difficulty": "beginner",
      "estimated_duration_days": 14,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-strength",
        "type": "primary",
        "category": "strength",
        "name": "Re-establish lower-body strength",
        "description": "Rebuild quad, glute, and hamstring strength through knee-safe ranges of motion to support return to skiing.",
        "milestones": [
          {
            "id": "ms-pain-free-squat",
            "name": "Complete all sessions pain-free with RPE ≤ 6",
            "reward_points": 50
          }
        ]
      },
      {
        "id": "goal-ski-return",
        "type": "secondary",
        "category": "sport_specific",
        "name": "Return to skiing next season",
        "description": "Build the neuromuscular base and single-leg stability required for safe alpine skiing.",
        "milestones": [
          {
            "id": "ms-single-leg-stability",
            "name": "Achieve 30-second single-leg balance on right leg with eyes closed",
            "reward_points": 75
          }
        ]
      }
    ],
