      "min_age": 18,
      "max_age": 60,
      "fitness_level": ["beginner", "intermediate"],
      "equipment": [
        {
          "id": "barbell",
          "name": "Barbell",
          "required": false,
          "alternatives": ["dumbbells"]
        },
        {
          "id": "dumbbells",
          "name": "Dumbbells",
          "required": true
        },
        {
          "id": "cable-machine",
          "name": "Cable Machine",
          "required": false,
          "alternatives": ["resistance-band"]
        },
        {
          "id": "leg-press",
          "name": "Leg Press Machine",
          "required": true
        },
        {
          "id": "bench",
          "name": "Flat Bench",
          "required": true
        }
      ],
      "contraindications": [
        {
          "condition": "icd10:S83.2",
          "severity": "high",
          "action": "exclude",
          "affected_activities": ["deep-squat", "jumping", "plyometrics", "full-knee-flexion-under-load"]
        },
        {
          "condition": "snomed:444798002",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": ["leg-press", "split-squat"]
        }
      ],
